package register_test

import (
	"testing"

	"github.com/jose-codegourmet/rotra-v2/apps/api/internal/writetest"
)

// The cases the TypeScript was captured with (apps/api/testdata/tools/capture-writes-player.test.mjs, group register, the cases
// generated by gen-writes-player-cases.py): every answer and the rows each registration left behind in the player, contact,
// RTR, account, claim-link, club, shared-entry and notification tables, and the audit events and notifications it did not write.
// The files live with the Player's own writes, which share the seed. Go answers differently from the Route Handler only where a
// step says "goExpects"; the session cookies are Go's own (the capture has no Supabase) and are asserted in cookies_test.go.
const testdata = "../../playerwrites/testdata"

func TestGolden(t *testing.T) { writetest.ReplayFull(t, testdata, "register", build) }
